<?php
declare(strict_types=1);require_once __DIR__.'/config/erp.php';$pdo=srnu_db();$fecha=$_GET['fecha']??$_POST['fecha']??date('Y-m-d');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$fecha))$fecha=date('Y-m-d');
function catmet(string $m):string{$m=mb_strtolower($m);if(str_contains($m,'efect'))return 'efectivo';if(str_contains($m,'trans'))return 'transferencias';if(str_contains($m,'tarjet')||str_contains($m,'clip')||str_contains($m,'bbva'))return 'tarjeta';return 'otros';}
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['guardar'])){$ef=efloat('efectivo');$tr=efloat('transferencias');$ta=efloat('tarjeta');$co=efloat('comisiones');$ot=efloat('otros');$esp=efloat('esperado');$real=efloat('real');$dif=round($real-$esp,2);$pdo->prepare('INSERT INTO cierres_caja(fecha,efectivo,transferencias,tarjeta,comisiones,otros,esperado,real_conciliado,diferencia,notas) VALUES(?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE efectivo=VALUES(efectivo),transferencias=VALUES(transferencias),tarjeta=VALUES(tarjeta),comisiones=VALUES(comisiones),otros=VALUES(otros),esperado=VALUES(esperado),real_conciliado=VALUES(real_conciliado),diferencia=VALUES(diferencia),notas=VALUES(notas)')->execute([$fecha,$ef,$tr,$ta,$co,$ot,$esp,$real,$dif,epost('notas')]);ego('caja.php?fecha='.$fecha);}
$st=$pdo->prepare('SELECT metodo,SUM(monto) total FROM pagos WHERE fecha=? GROUP BY metodo');$st->execute([$fecha]);$calc=['efectivo'=>0,'transferencias'=>0,'tarjeta'=>0,'otros'=>0];foreach($st as $r)$calc[catmet($r['metodo'])]+=(float)$r['total'];$g=$pdo->prepare('SELECT COALESCE(SUM(monto),0) FROM gastos WHERE fecha=?');$g->execute([$fecha]);$gastos=(float)$g->fetchColumn();$esperado=array_sum($calc)-$gastos;$s=$pdo->prepare('SELECT * FROM cierres_caja WHERE fecha=?');$s->execute([$fecha]);$c=$s->fetch()?:[];
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cierre de caja · SRNU</title><?=srnu_ui_head()?></head><body><?php srnu_appbar('finanzas');?><main class="w"><div class="srnu-page-heading"><div><h1>Cierre de caja</h1><p>Conciliación diaria de cobros y gastos.</p></div><a class="btn light" href="finanzas.php">← Finanzas</a></div><form class="toolbar" style="margin-bottom:16px"><input type="date" name="fecha" value="<?=eh($fecha)?>"><button class="btn">Ver día</button></form><div class="kpi-grid"><div class="kpi"><small>Efectivo registrado</small><strong><?=emoney($calc['efectivo'])?></strong></div><div class="kpi"><small>Transferencias</small><strong><?=emoney($calc['transferencias'])?></strong></div><div class="kpi"><small>Tarjeta</small><strong><?=emoney($calc['tarjeta'])?></strong></div><div class="kpi"><small>Gastos</small><strong><?=emoney($gastos)?></strong></div></div><section class="panel" style="padding:18px;margin-top:16px"><form method="post" class="erp-form cols-4"><input type="hidden" name="fecha" value="<?=eh($fecha)?>"><label>Efectivo<input type="number" step="0.01" name="efectivo" value="<?=eh($c['efectivo']??$calc['efectivo'])?>"></label><label>Transferencias<input type="number" step="0.01" name="transferencias" value="<?=eh($c['transferencias']??$calc['transferencias'])?>"></label><label>Tarjeta<input type="number" step="0.01" name="tarjeta" value="<?=eh($c['tarjeta']??$calc['tarjeta'])?>"></label><label>Comisiones terminal<input type="number" step="0.01" name="comisiones" value="<?=eh($c['comisiones']??0)?>"></label><label>Otros ingresos<input type="number" step="0.01" name="otros" value="<?=eh($c['otros']??$calc['otros'])?>"></label><label>Esperado neto<input type="number" step="0.01" name="esperado" value="<?=eh($c['esperado']??$esperado)?>"></label><label>Real contado/conciliado<input type="number" step="0.01" name="real" value="<?=eh($c['real_conciliado']??$esperado)?>"></label><input class="full" name="notas" placeholder="Notas de cierre" value="<?=eh($c['notas']??'')?>"><button class="btn blue" name="guardar" value="1">Guardar cierre</button></form><?php if($c):?><p><b>Diferencia guardada:</b> <?=emoney($c['diferencia'])?></p><?php endif;?></section></main></body></html>
